// Parametry raportu magazynu. Domyślnie czytamy data/suppliers; wywołanie przez webhook (/stock-report)
// działa tylko w trybie testowym (ALLOW_LLM_MOCK=1) i może wskazać inny katalog w data/ oraz klucz raportu.
// Z harmonogramu nie ma żadnego wejścia z zewnątrz.
const i = $input.first().json;
const viaWebhook = i.headers !== undefined;
const testMode = i.allowMock === '1';
const body = i.body && typeof i.body === 'object' ? i.body : {};

// ścieżka projektu trafia do polecenia w cudzysłowie, więc odrzucamy znaki specjalne powłoki
if (typeof i.projectDir !== 'string' || !i.projectDir || /["`$\\]/.test(i.projectDir)) throw new Error('INVALID_PROJECT_DIR');

let allowed = !viaWebhook || testMode;
let dir = 'suppliers';
if (viaWebhook && testMode && body.dir !== undefined) {
  if (typeof body.dir === 'string' && /^[a-z0-9_-]{1,40}$/.test(body.dir)) dir = body.dir;
  else allowed = false;
}
const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Warsaw' });
let key = today;
if (viaWebhook && testMode && body.digest_key !== undefined) {
  if (typeof body.digest_key === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(body.digest_key)) key = body.digest_key;
  else allowed = false;
}
return [{ json: { viaWebhook, allowed, dir, key, today, projectDir: i.projectDir } }];

// Parsuje cenniki hurtowni (połączone pliki CSV z polecenia cat): supplier,material,price.
// Obsługuje BOM, CRLF, pola w cudzysłowie z przecinkami, puste linie, komentarze (#) i powtórzony nagłówek.
// Ścisłość: wiersz musi mieć dokładnie 3 kolumny i domknięte cudzysłowy. Inne wiersze przechodzą dalej jako
// {raw} bez ceny, więc baza zgłosi je jako błędne zamiast zapisać po cichu część danych.
const raw = String($input.first().json.stdout || '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');

function parseLine(line) {
  const out = [];
  let cur = '';
  let quoted = false;
  for (let k = 0; k < line.length; k++) {
    const ch = line[k];
    if (quoted) {
      if (ch === '"' && line[k + 1] === '"') { cur += '"'; k++; }
      else if (ch === '"') quoted = false;
      else cur += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { out.push(cur); cur = ''; }
    else cur += ch;
  }
  out.push(cur);
  return { cols: out.map((c) => c.trim()), unterminated: quoted };
}

const rows = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (!t || t.startsWith('#')) continue;
  const { cols, unterminated } = parseLine(t);
  if (cols[0].toLowerCase() === 'supplier' && String(cols[1] || '').toLowerCase() === 'material') continue;
  if (unterminated || cols.length !== 3) { rows.push({ raw: t.slice(0, 200) }); continue; }
  rows.push({ supplier: cols[0], material: cols[1], price: cols[2] });
}
return [{ json: { rows } }];

// Składa podsumowanie dla właściciela: wynik importu cen i materiały do zamówienia.
// Wiadomość powstaje tylko wtedy, gdy jest o czym informować; klucz deduplikacji chroni przed dublem.
// Wspólne pomocniki stron HTML i komunikatów (wstawiane do węzłów Code przez n8n/build.mjs).
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const slackEsc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>]/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const page = (title, body, code = 200) => ({
  code,
  html: `<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">` +
    `<title>${esc(title)}</title><style>body{font-family:system-ui,sans-serif;max-width:34rem;margin:2rem auto;padding:0 1rem;color:#1a1a1a}` +
    `h1{font-size:1.3rem}button{font:inherit;padding:.6rem 1.2rem;border:0;border-radius:.4rem;background:#1f6feb;color:#fff;cursor:pointer}` +
    `select,input{font:inherit;padding:.5rem;width:100%;box-sizing:border-box;margin:.3rem 0 1rem}.err{color:#b42318}.ok{color:#067647}li{margin:.25rem 0}</style>` +
    `</head><body>${body}</body></html>`,
});
const pln = (x) => `${Number(x).toFixed(2).replace('.', ',')} zł`;
const isUuid = (s) => typeof s === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);

const params = $('Stock params').first().json;
const imp = $('Import prices').first().json;
const rep = $input.first().json;

const list = (a) => (Array.isArray(a) ? a : []);
const lines = [];
const issues = [];

if (imp.error) issues.push(`Import cenników nie powiódł się (${imp.error}).`);
if (list(imp.unknown_suppliers).length) issues.push(`Nieznane hurtownie: ${list(imp.unknown_suppliers).map(slackEsc).join(', ')}.`);
if (list(imp.unknown_materials).length) issues.push(`Nieznane materiały: ${list(imp.unknown_materials).map(slackEsc).join(', ')}.`);
if (list(imp.invalid).length) issues.push(`Błędnych wierszy: ${list(imp.invalid).length}.`);
if (!imp.error && Number(imp.updated) === 0) issues.push('Żadna cena nie została zaktualizowana (brak plików albo same błędne wiersze).');

const items = list(rep.items);
for (const it of items) {
  const where = it.best_supplier ? `najtaniej: ${slackEsc(it.best_supplier)} po ${pln(it.best_price)}` : 'brak aktualnej ceny';
  lines.push(`• ${slackEsc(it.name)}: dostępne ${Number(it.available)}, do zamówienia ${Number(it.to_order)}, ${where}`);
}
const unpriced = list(rep.unpriced);

if (!items.length && !issues.length) return [{ json: { p: [] } }];

const text = [
  `📦 Raport magazynu (${params.today})`,
  imp.error ? null : `Ceny hurtowni zaktualizowane: ${Number(imp.updated) || 0}.`,
  ...issues.map((x) => `⚠️ ${x}`),
  items.length ? `Do zamówienia (${items.length}):\n${lines.join('\n')}` : null,
  unpriced.length ? `Bez aktualnej ceny w hurtowniach: ${unpriced.map(slackEsc).join(', ')}.` : null,
].filter(Boolean).join('\n');

return [{ json: { p: [{ channel: 'slack', kind: 'stock_digest', dedupe_key: `stock-digest:${params.key}`, text: text.slice(0, 2900) }] } }];
